	"github.com/gin-gonic/gin"

	"github.com/luwa07832/idempotency-gateway/internal/store"
)

const (
	codeFingerprintConflict = "idempotency_fingerprint_conflict"
	codeInvalidRecord       = "invalid_idempotency_record"
	codeNotFound            = "not_found"
	codeInvalidCursor       = "invalid_cursor"
	codeStorageUnavailable  = "storage_unavailable"

	headerOutcome  = "Idempotency-Outcome"
	headerRecordID = "Idempotency-Record-ID"

	defaultPageLimit = 50
	maxPageLimit     = 100

	limitOutOfRangeMessage = "limit must be between 1 and 100"
)

// submitRequest is the only accepted body for record submission. Times are RFC 3339 UTC strings;
// response_snapshot is any JSON value and is replayed byte-for-byte as stored.
type submitRequest struct {
	IdempotencyKey     string          `json:"idempotency_key"`
	RequestFingerprint string          `json:"request_fingerprint"`
	ResponseSnapshot   json.RawMessage `json:"response_snapshot"`
	ExpiresAt          *string         `json:"expires_at"`
}

// validatedSubmitRequest carries the normalized fields of an accepted submission.
type validatedSubmitRequest struct {
	idempotencyKey     string
	requestFingerprint string
	responseSnapshot   json.RawMessage
	expiresAt          time.Time
}

// validateSubmitRequest enforces the fixed submission contract. The message return value carries
// the fixed message for InvalidIdempotencyRequest. Expiry must be strictly later than now: a
// timestamp equal to the creation moment is already expired and is rejected.
func validateSubmitRequest(rawBody []byte, now time.Time) (validatedSubmitRequest, string, bool) {
	var request submitRequest
	if err := json.Unmarshal(rawBody, &request); err != nil {
		return validatedSubmitRequest{}, "request body must be a single JSON object", false
	}
	if strings.TrimSpace(request.IdempotencyKey) == "" {
		return validatedSubmitRequest{}, "idempotency_key must not be empty", false
	}
	if strings.TrimSpace(request.RequestFingerprint) == "" {
		return validatedSubmitRequest{}, "request_fingerprint must not be empty", false
	}
	if request.ExpiresAt == nil || strings.TrimSpace(*request.ExpiresAt) == "" {
		return validatedSubmitRequest{}, "expires_at must be provided", false
	}
	expiresAt, err := time.Parse(time.RFC3339Nano, strings.TrimSpace(*request.ExpiresAt))
	if err != nil {
		return validatedSubmitRequest{}, "expires_at must be an RFC 3339 timestamp", false
	}
	expiresAt = expiresAt.UTC()
	if !expiresAt.After(now) {
		return validatedSubmitRequest{}, "expires_at must be later than the current time", false
	}
	snapshot := request.ResponseSnapshot
	if len(snapshot) == 0 {
		snapshot = json.RawMessage("null")
	}
	// Validate without a re-encoding round trip: both Unmarshal/Marshal and json.Compact drop
	// insignificant whitespace, but the first submission's exact JSON bytes must be stored and
	// replayed byte-for-byte.
	if !isValidJSONBytes(snapshot) {
		return validatedSubmitRequest{}, "response_snapshot must be valid JSON", false
	}
	return validatedSubmitRequest{
		idempotencyKey:     request.IdempotencyKey,
		requestFingerprint: request.RequestFingerprint,
		responseSnapshot:   snapshot,
		expiresAt:          expiresAt,
	}, "", true
}

// recordResponse lists its fields in the fixed order every record-shaped result uses.
type recordResponse struct {
	ID                 string          `json:"id"`
	IdempotencyKey     string          `json:"idempotency_key"`
	Status             string          `json:"status"`
	RequestFingerprint string          `json:"request_fingerprint"`
	ResponseSnapshot   json.RawMessage `json:"response_snapshot"`
	CreatedAt          string          `json:"created_at"`
	ExpiresAt          string          `json:"expires_at"`
}

type conflictBody struct {
	Code               string `json:"code"`
	Message            string `json:"message"`
	RecordID           string `json:"record_id"`
	RequestFingerprint string `json:"request_fingerprint"`
}

type errorBody struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

// pageCursor is the opaque continuation token. Only the last row's creation time and id are
// needed because ordering is (created_at DESC, id DESC).
type pageCursor struct {
	CreatedAt time.Time `json:"created_at"`
	ID        string    `json:"id"`
}

func (p pageCursor) encode() string {
	raw, _ := json.Marshal(p)
	return base64.RawURLEncoding.EncodeToString(raw)
}

func parsePageCursor(token string) (pageCursor, error) {
	raw, err := base64.RawURLEncoding.DecodeString(strings.TrimSpace(token))
	if err != nil {
		return pageCursor{}, err
	}
	var cursor pageCursor
	if err := json.Unmarshal(raw, &cursor); err != nil {
		return pageCursor{}, err
	}
	if cursor.ID == "" || cursor.CreatedAt.IsZero() {
		return pageCursor{}, errors.New("cursor missing fields")
	}
	return cursor, nil
}

func registerIdempotencyRoutes(router *gin.Engine, st *store.Store) {
	router.POST("/v1/idempotency/records", func(c *gin.Context) {
		handleSubmit(c, st)
	})
	router.GET("/v1/idempotency/conflicts", func(c *gin.Context) {
		handleListConflicts(c, st)
	})
	router.GET("/v1/idempotency/history", func(c *gin.Context) {
		handleListHistory(c, st)
	})
	router.GET("/v1/idempotency/records/:key", func(c *gin.Context) {
		handleGetRecord(c, st)
	})
	router.GET("/v1/idempotency/records-by-id/:record_id", func(c *gin.Context) {
		handleGetRecordByID(c, st)
	})
	router.GET("/v1/idempotency/records", func(c *gin.Context) {
		handleListRecords(c, st)
	})
}

func handleSubmit(c *gin.Context, st *store.Store) {
	now := time.Now().UTC()

	rawBody, err := io.ReadAll(c.Request.Body)
	if err != nil || len(bytes.TrimSpace(rawBody)) == 0 {
		writeInvalidRecord(c, "request body must be a single JSON object")
		return
	}
	validated, message, ok := validateSubmitRequest(rawBody, now)
	if !ok {
		writeInvalidRecord(c, message)
		return
	}

	id, err := store.NewRecordID()
	if err != nil {
		writeStorageUnavailable(c)
		return
	}
	candidate := store.Record{
		ID:                 id,
		IdempotencyKey:     validated.idempotencyKey,
		RequestFingerprint: validated.requestFingerprint,
		ResponseSnapshot:   validated.responseSnapshot,
		CreatedAt:          now,
		ExpiresAt:          validated.expiresAt,
	}

	record, outcome, err := st.PutRecord(c.Request.Context(), candidate, now)
	if err != nil {
		writeStorageUnavailable(c)
		return
	}
	switch outcome {
	case store.PutConflict:
		c.JSON(http.StatusConflict, gin.H{"error": conflictBody{
			Code:               codeFingerprintConflict,
			Message:            "a record with this idempotency key exists but its request fingerprint differs",
			RecordID:           record.ID,
			RequestFingerprint: record.RequestFingerprint,
		}})
	default:
		// PutCreated and PutReplayed share the exact same success envelope; only the outcome
		// header distinguishes the first insert from a byte-for-byte replay.
		outcomeLabel := "replayed"
		if outcome == store.PutCreated {
			outcomeLabel = "created"
		}
		c.Header(headerOutcome, outcomeLabel)
		c.Header(headerRecordID, record.ID)
		writeRecordEnvelope(c, toRecordResponse(record))
	}
}

func handleGetRecord(c *gin.Context, st *store.Store) {
	key := c.Param("key")
	if strings.TrimSpace(key) == "" {
		writeNotFound(c)
		return
	}
	record, err := st.ActiveRecordByKey(c.Request.Context(), key, time.Now().UTC())
	if err != nil {
		writeStorageUnavailable(c)
		return
	}
	if record == nil {
		writeNotFound(c)
		return
	}
	writeRecordEnvelope(c, toRecordResponse(record))
}

// handleGetRecordByID serves the read-only lookup of any record generation, including expired
// ones. A malformed id is a client error and never reaches storage; a well-formed but unknown id
// is 404. The endpoint writes nothing and does not change what any other endpoint exposes.
func handleGetRecordByID(c *gin.Context, st *store.Store) {
	recordID := c.Param("record_id")
	if !store.IsRecordID(recordID) {
		writeInvalidRecord(c, "record_id must be \"rec_\" followed by 32 lowercase hexadecimal characters")
		return
	}
	record, err := st.RecordByID(c.Request.Context(), recordID)
	if err != nil {
		writeStorageUnavailable(c)
		return
	}
	if record == nil {
		writeRecordNotFound(c)
		return
	}
	response := toRecordResponse(record)
	// Status is derived at query time: only an expiry strictly later than now keeps the record
	// active; equality already means expired.
	if !record.ExpiresAt.After(time.Now().UTC()) {
		response.Status = "expired"
	}
	writeRecordEnvelope(c, response)
}

func handleListRecords(c *gin.Context, st *store.Store) {
	now := time.Now().UTC()
	filter := store.ListFilter{Limit: defaultPageLimit}

	if key := strings.TrimSpace(c.Query("key")); key != "" {
		filter.IdempotencyKey = key
	}
	// The fingerprint is matched character-for-character: the raw query value is used as-is with
	// no trimming, case folding or other normalization. Only the empty (absent) value falls back
	// to the unfiltered baseline; a whitespace-only value is still a real filter that matches
	// nothing.
	filter.RequestFingerprint = c.Query("request_fingerprint")

	switch strings.TrimSpace(c.Query("status")) {
	case "", "active":
	case "expired":
	default:
		writeInvalidRecord(c, "status must be active or expired")
		return
	}

	if raw := strings.TrimSpace(c.Query("expires_before")); raw != "" {
		parsed, ok := parseQueryTime(c, raw)
		if !ok {
			return
		}
		filter.ExpiresBefore = &parsed
	}
	if raw := strings.TrimSpace(c.Query("expires_after")); raw != "" {
		parsed, ok := parseQueryTime(c, raw)
		if !ok {
			return
		}
		filter.ExpiresAfter = &parsed
	}

	if rawLimit := strings.TrimSpace(c.Query("limit")); rawLimit != "" {
		limit, ok := parseQueryLimit(c, rawLimit)
		if !ok {
			return
		}
		filter.Limit = limit
	}

	if rawCursor := strings.TrimSpace(c.Query("cursor")); rawCursor != "" {
		cursor, err := parsePageCursor(rawCursor)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": errorBody{
				Code:    codeInvalidCursor,
				Message: "pagination cursor is invalid",
			}})
			return
		}
		filter.CursorCreatedAt = cursor.CreatedAt
		filter.CursorID = cursor.ID
	}

	// Expired records never participate in normal results; the page is deterministically empty
	// rather than surfacing historical snapshots. Parameters above are still validated first.
	if strings.TrimSpace(c.Query("status")) == "expired" {
		writeListResponse(c, nil, "")
		return
	}

	// Fetch one extra row to decide whether another page exists without an unstable total count.
	filter.Limit++
	records, err := st.ListRecords(c.Request.Context(), filter, now)
	if err != nil {
		writeStorageUnavailable(c)
		return
	}

	nextCursor := ""
	if len(records) == filter.Limit {
		last := records[len(records)-2]
		nextCursor = pageCursor{CreatedAt: last.CreatedAt, ID: last.ID}.encode()
		records = records[:len(records)-1]
	}

	page := make([]recordResponse, 0, len(records))
	for i := range records {
		page = append(page, toRecordResponse(&records[i]))
	}
	writeListResponse(c, page, nextCursor)
}

func parseQueryTime(c *gin.Context, raw string) (time.Time, bool) {
	parsed, err := time.Parse(time.RFC3339Nano, raw)
	if err != nil {
		writeInvalidRecord(c, "time filters must be RFC 3339 timestamps")
		return time.Time{}, false
	}
	return parsed.UTC(), true
}

// handleListHistory serves the read-only expired-record audit. It only ever returns rows that
// were already expired when the query ran; the active endpoints keep their own response and error
// semantics and never surface these snapshots. The query is read-only: no row is inserted,
// rewritten, merged or deleted, and an unknown key is an empty page rather than a placeholder.
func handleListHistory(c *gin.Context, st *store.Store) {
	now := time.Now().UTC()

	key := strings.TrimSpace(c.Query("key"))
	if key == "" {
		writeInvalidRecord(c, "key must identify an idempotency key")
		return
	}
	filter := store.HistoryFilter{
		IdempotencyKey:     key,
		RequestFingerprint: c.Query("request_fingerprint"),
		Limit:              defaultPageLimit,
	}

	if raw := strings.TrimSpace(c.Query("expires_before")); raw != "" {
		parsed, ok := parseQueryTime(c, raw)
		if !ok {
			return
		}
		filter.ExpiresBefore = &parsed
	}
	if raw := strings.TrimSpace(c.Query("expires_after")); raw != "" {
		parsed, ok := parseQueryTime(c, raw)
		if !ok {
			return
		}
		filter.ExpiresAfter = &parsed
	}

	if rawLimit := strings.TrimSpace(c.Query("limit")); rawLimit != "" {
		limit, ok := parseQueryLimit(c, rawLimit)
		if !ok {
			return
		}
		filter.Limit = limit
	}

	if rawCursor := strings.TrimSpace(c.Query("cursor")); rawCursor != "" {
		cursor, err := parsePageCursor(rawCursor)
		if err != nil {
			writeInvalidCursor(c)
			return
		}
		filter.CursorCreatedAt = cursor.CreatedAt
		filter.CursorID = cursor.ID
	}

	// Fetch one extra row to decide whether another page exists without an unstable total count.
	filter.Limit++
	records, err := st.ListHistoryRecords(c.Request.Context(), filter, now)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrInvalidID), errors.Is(err, store.ErrCursorTarget):
			writeInvalidCursor(c)
		default:
			writeStorageUnavailable(c)
		}
		return
	}

	nextCursor := ""
	if len(records) == filter.Limit {
		last := records[len(records)-2]
		nextCursor = pageCursor{CreatedAt: last.CreatedAt, ID: last.ID}.encode()
		records = records[:len(records)-1]
	}

	page := make([]recordResponse, 0, len(records))
	for i := range records {
		page = append(page, toHistoryRecordResponse(&records[i]))
	}
	writeListResponse(c, page, nextCursor)
}

// toHistoryRecordResponse renders one expired generation with the same fixed field order as
// active records; only status differs ("expired") and the snapshot is replayed byte-for-byte.
func toHistoryRecordResponse(record *store.Record) recordResponse {
	response := toRecordResponse(record)
	response.Status = "expired"
	return response
}

func writeInvalidCursor(c *gin.Context) {
	c.JSON(http.StatusBadRequest, gin.H{"error": errorBody{
		Code:    codeInvalidCursor,
		Message: "pagination cursor is invalid",
	}})
}

func parseQueryLimit(c *gin.Context, raw string) (int, bool) {
	limit := 0
	for _, digit := range raw {
		if digit < '0' || digit > '9' {
			writeInvalidRecord(c, "limit must be a positive integer")
			return 0, false
		}
		limit = limit*10 + int(digit-'0')
		if limit > maxPageLimit {
			limit = maxPageLimit + 1
		}
	}
	if limit < 1 || limit > maxPageLimit {
		writeInvalidRecord(c, limitOutOfRangeMessage)
		return 0, false
	}
	return limit, true
}

func toRecordResponse(record *store.Record) recordResponse {
	return recordResponse{
		ID:                 record.ID,
		IdempotencyKey:     record.IdempotencyKey,
		Status:             "active",
		RequestFingerprint: record.RequestFingerprint,
		ResponseSnapshot:   record.ResponseSnapshot,
		CreatedAt:          record.CreatedAt.Format(time.RFC3339Nano),
		ExpiresAt:          record.ExpiresAt.Format(time.RFC3339Nano),
	}
}

// isValidJSONBytes reports whether raw is exactly one complete JSON value, without re-encoding
// (and therefore without normalizing) its bytes.
func isValidJSONBytes(raw []byte) bool {
	decoder := json.NewDecoder(bytes.NewReader(raw))
	var value any
	if err := decoder.Decode(&value); err != nil {
		return false
	}
	var trailing any
	if err := decoder.Decode(&trailing); err != io.EOF {
		return false
	}
	return true
}

func writeInvalidRecord(c *gin.Context, message string) {
	c.JSON(http.StatusBadRequest, gin.H{"error": errorBody{Code: codeInvalidRecord, Message: message}})
}

func writeNotFound(c *gin.Context) {
	c.JSON(http.StatusNotFound, gin.H{"error": errorBody{
		Code:    codeNotFound,
		Message: "no active idempotency record exists for this key",
	}})
}

func writeRecordNotFound(c *gin.Context) {
	c.JSON(http.StatusNotFound, gin.H{"error": errorBody{
		Code:    codeNotFound,
		Message: "no idempotency record exists for this record id",
	}})
}

func writeStorageUnavailable(c *gin.Context) {
	c.JSON(http.StatusServiceUnavailable, gin.H{"error": errorBody{
		Code:    codeStorageUnavailable,
		Message: "database is not available",
	}})
}
package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/idempotency-gateway/internal/store"
)

// NewRouter wires the public HTTP surface. Only the health entry is published today; the service
// contract in README.md describes the error shape every entry must keep.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	registerIdempotencyRoutes(router, st)

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}
package api

import (
	"bytes"
	"encoding/json"
	"net/http"

	"github.com/gin-gonic/gin"
)

// marshalRecordObject renders one record with the fixed field order while embedding
// response_snapshot's stored bytes verbatim. encoding/json compacts every nested JSON value
// (including json.RawMessage) during marshaling, so the snapshot is concatenated in place rather
// than passed through an encoder; it is guaranteed to be valid JSON at submission time.
func marshalRecordObject(record recordResponse) ([]byte, error) {
	id, err := json.Marshal(record.ID)
	if err != nil {
		return nil, err
	}
	key, err := json.Marshal(record.IdempotencyKey)
	if err != nil {
		return nil, err
	}
	status, err := json.Marshal(record.Status)
	if err != nil {
		return nil, err
	}
	fingerprint, err := json.Marshal(record.RequestFingerprint)
	if err != nil {
		return nil, err
	}
	createdAt, err := json.Marshal(record.CreatedAt)
	if err != nil {
		return nil, err
	}
	expiresAt, err := json.Marshal(record.ExpiresAt)
	if err != nil {
		return nil, err
	}
	snapshot := record.ResponseSnapshot
	if len(snapshot) == 0 {
		snapshot = []byte("null")
	}

	var body bytes.Buffer
	body.Grow(len(id) + len(key) + len(status) + len(fingerprint) + len(createdAt) + len(expiresAt) + len(snapshot) + 128)
	body.WriteString(`{"id":`)
	body.Write(id)
	body.WriteString(`,"idempotency_key":`)
	body.Write(key)
	body.WriteString(`,"status":`)
	body.Write(status)
	body.WriteString(`,"request_fingerprint":`)
	body.Write(fingerprint)
	body.WriteString(`,"response_snapshot":`)
	body.Write(snapshot)
	body.WriteString(`,"created_at":`)
	body.Write(createdAt)
	body.WriteString(`,"expires_at":`)
	body.Write(expiresAt)
	body.WriteByte('}')
	return body.Bytes(), nil
}

// writeRecordEnvelope writes {"record":{...}} with the snapshot bytes untouched.
func writeRecordEnvelope(c *gin.Context, record recordResponse) {
	object, err := marshalRecordObject(record)
	if err != nil {
		writeStorageUnavailable(c)
		return
	}
	body := make([]byte, 0, len(object)+11)
	body = append(body, `{"record":`...)
	body = append(body, object...)
	body = append(body, '}')
	c.Data(http.StatusOK, "application/json; charset=utf-8", body)
}

// writeListResponse writes {"records":[...],"next_cursor":...} with every snapshot untouched.
func writeListResponse(c *gin.Context, records []recordResponse, nextCursor string) {
	encodedCursor, err := json.Marshal(nextCursor)
	if err != nil {
		writeStorageUnavailable(c)
		return
	}

	var body bytes.Buffer
	body.WriteString(`{"records":[`)
	for i := range records {
		if i > 0 {
			body.WriteByte(',')
		}
		object, err := marshalRecordObject(records[i])
		if err != nil {
			writeStorageUnavailable(c)
			return
		}
		body.Write(object)
	}
	body.WriteString(`],"next_cursor":`)
	body.Write(encodedCursor)
	body.WriteByte('}')
	c.Data(http.StatusOK, "application/json; charset=utf-8", body.Bytes())
}

